};
const q = (query || '').toLowerCase();
const key = Object.keys(catalogo).find(k => q.includes(k) || k.includes(q));
if (!key) return 'Producto no encontrado. Productos disponibles: ' + Object.keys(catalogo).join(', ');
const p = catalogo[key];
return JSON.stringify({ producto: key, stock: p.stock, precio_ARS: p.precio, entrega: p.demora });

const tarifas = { 'caba': [15000,'24-48 h'], 'buenos aires': [22000,'48-72 h'], 'córdoba': [38000,'3-5 días hábiles'], 'santa fe': [35000,'3-5 días hábiles'], 'mendoza': [45000,'5-7 días hábiles'] };
const q = (query||'').toLowerCase();
const k = Object.keys(tarifas).find(x => q.includes(x));
return k ? JSON.stringify({ destino: k, costo_ARS: tarifas[k][0], demora: tarifas[k][1] }) : 'Destino sin tarifa cargada: derivar a ventas.';

const pedidos = { 'R-1042': 'En fabricación, sale del taller el viernes', 'R-1043': 'Despachado, llega en 48 h', 'R-1044': 'Entregado' };
const id = (query||'').toUpperCase().match(/R-\d+/)?.[0];
return pedidos[id] || 'No encontré ese pedido. Pedile al cliente el número con formato R-XXXX.';

const cupones = { 'ROBLE10': 10, 'BIENVENIDA15': 15 };
const c = (query||'').toUpperCase().trim();
return cupones[c] ? 'Cupón válido: ' + cupones[c] + '% de descuento.' : 'Cupón inválido o vencido.';

