const armar = (tools) => ({
  generateContentRequest: {
    model: 'models/' + modelo,
    systemInstruction: { parts: [{ text: systemPrompt }] },
    contents: [{ role: 'user', parts: [{ text: pregunta }] }],
    tools: [{ functionDeclarations: tools }]
  }
});

return [
  { json: { escenario: '1 herramienta', cantidad: 1, modelo, body: armar(herramientas.slice(0, 1)) } },
  { json: { escenario: '10 herramientas', cantidad: 10, modelo, body: armar(herramientas) } }
];

// Junta los resultados de countTokens y calcula el overhead
const pedidos = $('Armar pedido: 1 vs 10 tools').all();
const res = $input.all().map((it, i) => ({
  escenario: pedidos[i].json.escenario,
  promptTokens: it.json.totalTokens
}));
const t1 = res[0].promptTokens, t10 = res[1].promptTokens;
const overhead = t10 - t1;
return [{ json: {
  tokens_con_1_herramienta: t1,
  tokens_con_10_herramientas: t10,
  overhead_por_llamada: overhead,
  overhead_por_pregunta_2_llamadas: overhead * 2,
  overhead_1000_preguntas: overhead * 2 * 1000,
  explicacion: 'Cada llamada al modelo vuelve a mandar la definición de TODAS las herramientas. Con 2 llamadas por pregunta (decide herramienta + responde), el overhead se paga 2 veces.'
} }];
